trigger.script:
local posr1 = random(10) local posrr1={ CVector(7096.887, 251.511, 524.762), CVector(6494.388, 256.065, 791.483), CVector(5533.235, 247.101, 646.046), CVector(6999.741, 246.419, 859.777), CVector(7135.897, 270.999, 1594.224), CVector(6546.896, 256.152, 2260.690), CVector(6117.170, 270.138, 2561.633), CVector(7371.443, 223.531, 1960.418), CVector(7999.273, 226.466, 2746.604), CVector(6879.807, 226.949, 3461.883)}
local posr2 = random(10) local posrr2={ CVector(5770.631, 208.864, 4243.322), CVector(5666.647, 212.885, 4777.477), CVector(4900.090, 233.795, 4973.739), CVector(4514.838, 242.744, 4715.496), CVector(4201.402, 261.296, 3874.374), CVector(4605.746, 265.409, 3405.248), CVector(4304.126, 247.700, 2415.274), CVector(3975.037, 244.840, 769.116), CVector(4399.409, 214.824, 928.731), CVector(4479.127, 212.037, 1279.993)}
local posr_scav1={ CVector(5613.020, 216.573, 1084.168), CVector(5852.572, 238.424, 1135.578), CVector(5987.480, 245.991, 871.976), CVector(7355.271, 249.227, 2411.834), CVector(7345.678, 226.972, 2850.049), CVector(7237.014, 219.630, 3166.718), CVector(6792.051, 250.218, 3013.096), CVector(5412.767, 228.956, 2206.780)}
local posr_scav2={ CVector(5277.207, 237.487, 5201.297), CVector(5233.958, 263.437, 4815.378), CVector(5007.909, 234.721, 5327.070), CVector(4705.930, 280.920, 4204.618), CVector(4606.604, 280.868, 3953.746), CVector(3964.326, 251.492, 1790.708), CVector(4611.425, 247.476, 2544.672)}
local rotarr={ Quaternion(-0.029, 0.679, -0.021, 0.734), Quaternion(0.001, 0.626, 0.002, 0.780), Quaternion(-0.001, 0.558, -0.001, 0.830), Quaternion(-0.029, -0.025, 0.005, 0.999), Quaternion(-0.001, -0.346, 0.001, 0.938), Quaternion(-0.001, -0.724, -0.000, 0.690), Quaternion(-0.025, -0.992, -0.005, 0.125), Quaternion(0.002, -0.914, -0.001, 0.405), Quaternion(-0.003, -1.000, -0.006, -0.015)}
local spawns = random(2) if spawns == 1 then SetVar("SpawnPlayer", 1) if not(GetVar("PlayerBelong").AsString == "SCAV") then SetVar("PosPlayer1", posr1) TActivate("ExitsForPMC_2") end else SetVar("SpawnPlayer", 2) if not(GetVar("PlayerBelong").AsString == "SCAV") then SetVar("PosPlayer2", posr2) TActivate("ExitsForPMC_1") end end
local vehPlayer = GetPlayerVehicle() if vehPlayer then vehPlayer:SetRotation(rotarr[random(getn(rotarr))]) vehPlayer:setImmortalMode(1) if spawns == 1 then if not(GetVar("PlayerBelong").AsString == "SCAV") then vehPlayer:SetGamePositionOnGround(posrr1[posr1]) else vehPlayer:SetGamePositionOnGround(posr_scav1[random(getn(posr_scav1))]) end else if not(GetVar("PlayerBelong").AsString == "SCAV") then vehPlayer:SetGamePositionOnGround(posrr2[posr2]) else vehPlayer:SetGamePositionOnGround(posr_scav2[random(getn(posr_scav2))]) end end if GetVar("PlayerBelong").AsString == "SCAV" then vehPlayer:SetNameFromScript("ScavCarForPlayer") getObj("FakePlayerDead"):DelEvent("GE_VEHICLE_WITHOUT_HEALTH") getObj("FakePlayerDead"):AddEvent("GE_VEHICLE_WITHOUT_HEALTH", "ScavCarForPlayer") getObj("DotShoot"):DelEvent("GE_UNDER_ATTACK") getObj("DotShoot"):AddEvent("GE_UNDER_ATTACK", "ScavCarForPlayer") TActivate("ExitsForScavs") else vehPlayer:SetNameFromScript("PlayerCar") getObj("FakePlayerDead"):DelEvent("GE_VEHICLE_WITHOUT_HEALTH") getObj("FakePlayerDead"):AddEvent("GE_VEHICLE_WITHOUT_HEALTH", "PlayerCar") getObj("DotShoot"):DelEvent("GE_UNDER_ATTACK") getObj("DotShoot"):AddEvent("GE_UNDER_ATTACK", "PlayerCar") end vehPlayer:SetThrottle(0) vehPlayer:SetCustomLinearVelocity(0) end
TActivate("SpawnsScavs") TActivate("FakePlayerDead")
if GetVar("PlayerBelong").AsString ~= "SCAV" then if EVENT == "1_APRIL" or EVENT == "1_APRIL_MULTIPLAYER" then TActivate("TpFollowPlayerCarsToPlayer") end end
trigger:Deactivate()

local enemylist = {"Sml1CarScav", "Sml2CarScav", "Sml3CarScav", "Sml4CarScav", "Scout1CarScav", "Scout2CarScav", "Scout3CarScav", "Fighter1CarScav", "Fighter2CarScav", "Hunter2CarScav"} local smallgunlist = {"hornet01","specter01","storm01","pkt01","kord01","maxim01","fagot01"} local biggunlist = {"vector01","vulcan01","rapier01","bumblebee01","kpvt01"}
local pos={ CVector(5613.020, 216.573, 1084.168), CVector(5852.572, 238.424, 1135.578), CVector(5987.480, 245.991, 871.976), CVector(7355.271, 249.227, 2411.834), CVector(7345.678, 226.972, 2850.049), CVector(7237.014, 219.630, 3166.718), CVector(6792.051, 250.218, 3013.096), CVector(5412.767, 228.956, 2206.780),
CVector(5277.207, 237.487, 5201.297), CVector(5233.958, 263.437, 4815.378), CVector(5007.909, 234.721, 5327.070), CVector(4705.930, 280.920, 4204.618), CVector(4606.604, 280.868, 3953.746), CVector(3964.326, 251.492, 1790.708), CVector(4611.425, 247.476, 2544.672)}
local rotarr={ Quaternion(-0.029, 0.679, -0.021, 0.734), Quaternion(0.001, 0.626, 0.002, 0.780), Quaternion(-0.001, 0.558, -0.001, 0.830), Quaternion(-0.029, -0.025, 0.005, 0.999), Quaternion(-0.001, -0.346, 0.001, 0.938), Quaternion(-0.001, -0.724, -0.000, 0.690), Quaternion(-0.025, -0.992, -0.005, 0.125), Quaternion(0.002, -0.914, -0.001, 0.405), Quaternion(-0.003, -1.000, -0.006, -0.015)}
local scav_count = random(5,8) local paths_pos = shuffled_range_take(scav_count, 1, 15) local path = {CVector(7000.846, 245.680, 883.056), CVector(6482.714, 252.667, 505.857), CVector(5812.392, 237.971, 1012.158), CVector(6187.649, 246.986, 1326.348), CVector(5178.703, 229.098, 1967.525), CVector(5997.672, 281.777, 2414.217), CVector(6320.488, 226.283, 1909.103), CVector(7362.553, 232.040, 1653.414), CVector(7496.263, 229.482, 3079.413), CVector(6061.996, 353.897, 2725.391), CVector(5857.956, 210.842, 4513.463), CVector(5783.563, 207.345, 4290.824), CVector(5171.967, 268.412, 4904.286), CVector(5339.696, 264.556, 4983.745), CVector(4618.079, 279.012, 3992.218), CVector(3634.397, 254.245, 2291.421), CVector(4674.244, 252.267, 2283.145), CVector(4570.031, 254.090, 1784.210), CVector(4126.987, 232.639, 1188.829), CVector(3915.370, 244.468, 1590.822), CVector(6618.849, 204.041, 1151.253)} for j=1,scav_count do local num = paths_pos[j] local model = enemylist[random(getn(enemylist))]
TeamCreate("Scav_"..j, 1082, pos[num], {model}, nil, 1)
local sv = GetEntityByName ("Scav_"..j.."_vehicle_0") local pl = GetPlayerVehicle() if sv and pl then local len = Dist(pl, sv) if 300 > len then sv:Remove() else sv:SetRotation(rotarr[random(9)]) sv:SetNewPart("CABIN_SMALL_GUN",smallgunlist[exrandom(getn(smallgunlist))]) if model == "Fighter2CarScav" or model == "Hunter2CarScav" then sv:SetNewPart("CABIN_BIG_GUN_1",biggunlist[exrandom(getn(biggunlist))]) end AddAmmoItemsForGuns(sv, random(0,1)) end end
local sv_way = GetEntityByName ("Scav_"..j) if sv_way then sv_way:SetDestination(path[random(21)]) end end
for i=1,scav_count do local veh = getObj("Scav_"..i.."_vehicle_0") if veh then getObj("Scavs_Reached"):AddEvent("GE_TARGET_REACHED", "Scav_"..i) getObj("Scavs_Dead"):AddEvent("GE_OBJECT_DIE", "Scav_"..i.."_vehicle_0") getObj("Scavs_UnderAttack"):AddEvent("GE_UNDER_ATTACK", "Scav_"..i.."_vehicle_0") SetVar("Scav_"..i.."_vehicle_0_UnderAttack", 0) end end
TActivate("Scavs_Reached") TActivate("Scavs_Dead") TActivate("Scavs_UnderAttack") SetVar("CountScavs", scav_count) trigger:Deactivate()

local newControllerId = CreateNewObject { prototypeName = "someNPCMotionController", objName = "ControllerScavCarFollow" }
local newController = GetEntityByID(newControllerId) local FVehicle = GetEntityByName("ScavCarFollow_vehicle_0") if FVehicle then newController:setVehicleUnderControl(FVehicle) end
AddImportantFadingMsgByStrIdFormatted("fm_scav_follow_to_player") SoundFadingMsg()
if getObj("ScavCarDist"):IsActivated() == 0 then TActivate("ScavCarDist") end TActivate("ScavCarFollowDie") trigger:Deactivate()

local barrel = {"BarrelBox_1_loc", "BarrelBox_2_loc", "BarrelBox_3_loc", "BarrelBox_5_loc", "BarrelBox_7_loc", "BarrelBox_8_loc", "BarrelBox_10_loc", "BarrelBox_14_loc", "BarrelBox_15_loc", "BarrelBox_16_loc", "BarrelBox_19_loc", "BarrelBox_21_loc", "BarrelBox_25_loc", "BarrelBox_27_loc", "BarrelBox_30_loc", "BarrelBox_32_loc", "BarrelBox_33_loc", "BarrelBox_34_loc", "BarrelBox_35_loc", "BarrelBox_36_loc", "BarrelBox_41_loc"} local cache = {"BarrelBox_4_loc", "BarrelBox_6_loc", "BarrelBox_9_loc", "BarrelBox_11_loc", "BarrelBox_12_loc", "BarrelBox_13_loc", "BarrelBox_17_loc", "BarrelBox_18_loc", "BarrelBox_20_loc", "BarrelBox_22_loc", "BarrelBox_23_loc", "BarrelBox_24_loc", "BarrelBox_26_loc", "BarrelBox_28_loc", "BarrelBox_29_loc", "BarrelBox_31_loc", "BarrelBox_37_loc", "BarrelBox_38_loc", "BarrelBox_39_loc", "BarrelBox_40_loc"}
for b = 1, 21 do if random(2) == 1 then CreateBarrelLootBox("barrel"..b, getPos(barrel[b])) end end
for c = 1, 20 do if random(2) == 1 then CreateBarrelLootBox("cache"..c, getPos(cache[c]), getObj(cache[c]):GetRotation(), 2) local BarrelPos = getObj("cache"..c):GetPosition() if c == 5 or c == 20 then BarrelPos.y = BarrelPos.y + 0.060 getObj("cache"..c):SetPosition(BarrelPos) elseif c == 4 then BarrelPos.y = BarrelPos.y - 0.060 getObj("cache"..c):SetPosition(BarrelPos) end end end trigger:Deactivate()

local items = {"potato", "scrap_metal", "firewood", "oil", "bottle", "fuel", "machinery", "tobacco", "book", "electronics", "doski", "details", "shkatulka", "scrap_metal_use", "machinery_use", "oil_use", "fuel_nil_use", "item_key_gate_bunker014", "item_green_fier", "ammo_chest_machinegun", "ammo_chest_shotgun", "item_bolts", "item_datchik", "item_hose", "item_insulation", "item_nails", "item_nuts", "item_parts", "item_pena", "item_plex", "item_poheram", "item_scotch", "item_screws", "item_thermometer", "item_tube", "item_cable", "item_cooler", "item_cpu", "item_drill", "item_dvd", "item_electronics_components", "item_energo_lump", "item_gazan", "item_geiger", "item_hdd", "item_helix", "item_kondesators", "item_lcd", "item_lump", "item_magnet", "item_phone", "item_plate", "item_ram", "item_rele", "item_svech", "item_tplug", "item_ultra_lump", "item_usb", "item_wires", "item_accum", "item_battery_aa", "item_battery_d", "item_cyclon", "item_green_battery", "item_powerbank", "item_dry", "item_hunter_spich", "item_lighter", "item_spich", "item_survl", "item_termit", "item_trotile", "item_wd40_100", "item_wd40_400", "item_zibbo", "item_gunpowder", "item_sugar", "item_sausage", "item_alkani", "item_hlor", "item_paper", "item_salt", "item_soap", "item_soda", "item_tb", "item_toothpaste", "item_diary", "item_diary_s", "item_disk", "item_flashdrive", "item_manual", "item_sas", "item_ssd", "item_aquapeps", "item_c6h8o6", "item_h2o2", "item_medical_tools", "item_naci", "item_suringe", "item_afak", "item_ai2", "item_analgin", "item_carmed", "item_grizzly", "item_ifak", "item_med", "item_morfie", "item_salewa", "item_vazelin", "item_zvezda", "item_filter", "item_paracord", "item_vodka", "item_waterfilter", "item_zapal", "item_carsen", "item_stakanyash", "item_awl", "item_fullmaster", "item_leatherman", "item_metalscissors", "item_nippers", "item_pliers", "item_pliers_round", "item_roulet", "item_screw", "item_screw_flat", "item_screw_flat_long", "item_sewing_kit", "item_toolset", "item_wrench", "item_chain", "item_chain_gold", "item_ex", "item_rolex", "item_teapon", "item_woodclock", "item_silver_skull", "item_duck"} local gun = {"hornet01", "specter01", "pkt01", "kord01", "storm01", "vector01", "vulcan01", "kpvt01", "rapier01", "omega01", "bumblebee01"} local gadget1 = {"additional_fuel_tank", "additional_torque", "additional_durability", "additional_stability", "cooling_system_guns", "cooling_system_energy", "cooling_system_explosion", "firing_rate_guns", "firing_rate_energy", "grouping_angle_guns", "add_damage_guns", "add_damage_energy", "add_damage_explosion", "firing_range_guns"} local gadget2 = {"cooling_system_guns2", "cooling_system_energy2", "cooling_system_explosion2", "firing_rate_guns2", "firing_rate_energy2", "grouping_angle_guns2", "add_damage_guns2", "add_damage_energy2", "add_damage_explosion2", "additional_fuel_tank2", "additional_torque2", "additional_durability2"}
local protChest = "mainChest" if EVENT == "NEW_YEAR" then local new_items = {"item_christmas_ball_blue", "item_christmas_ball_red", "item_christmas_ball_white", "item_christmas_star"} for i = 1, 4 do table.insert(items, new_items[i]) end protChest = "christmasChest" end
for i=1,12 do local Chest = CreateNewObject{prototypeName = protChest, objName = "DeadScav"..i.."Chest"} local ChestId = GetEntityByID(Chest) ChestId:SetPosition(CVector(getPos("DeadScavBox_"..i.."_loc"))) ChestId:SetRotation(getObj("DeadScavBox_"..i.."_loc"):GetRotation())
if random(3) == 1 then AddGunRandomAmmoToChestObj(ChestId, gun[random(getn(gun))], "ScavItemGun_"..random(10000)) end
if random(5) == 1 then local gadget_rand = {gadget1[random(getn(gadget1))], gadget2[random(getn(gadget2))]} AddItemsToChestObj(ChestId, gadget_rand[random(2)], "ScavItemGadget_"..random(10000)) end
for i = 1, random(4) do local item = GetRandomWeightedItem(items) AddItemsToChestObj(ChestId, item, "ScavItem_"..random(10000)) end
if i == 9 then if random(3) == 1 then AddItemsToChestObj(ChestId, "item_green_fier", "ScavItemGreenFier_"..random(10000)) end end
if random(2) == 1 then AddItemsToChestObj(ChestId, "item_vodka", "ScavItemVodka_"..random(10000)) end end trigger:Deactivate()

local small_gun_box = {"GunBox_1_loc", "GunBox_3_loc", "GunBox_9_loc", "GunBox_10_loc", "GunBox_14_loc", "GunBox_17_loc", "GunBox_20_loc", "GunBox_24_loc", "GunBox_26_loc", "GunBox_27_loc", "GunBox_28_loc", "GunBox_33_loc", "GunBox_39_loc", "GunBox_40_loc"} local big_gun_box_black = {"GunBox_11_loc", "GunBox_12_loc", "GunBox_25_loc", "GunBox_30_loc", "GunBox_36_loc"} local big_gun_box_green = {"GunBox_2_loc", "GunBox_38_loc"} local flat_gun_box = {"GunBox_4_loc", "GunBox_5_loc", "GunBox_6_loc", "GunBox_7_loc", "GunBox_8_loc", "GunBox_13_loc", "GunBox_15_loc", "GunBox_16_loc", "GunBox_18_loc", "GunBox_19_loc", "GunBox_21_loc", "GunBox_22_loc", "GunBox_23_loc", "GunBox_29_loc", "GunBox_31_loc", "GunBox_32_loc", "GunBox_34_loc", "GunBox_35_loc", "GunBox_37_loc"}
for s=1,14 do if random(2) == 1 then CreateSmallGunBox("SmallGunBox"..s, getPos(small_gun_box[s]), getObj(small_gun_box[s]):GetRotation()) if s == 12 then getObj("SmallGunBox12"):SetPropertyById(7, 0.4) end end end
for b=1,5 do if random(2) == 1 then CreateBigGunBoxBlack("BigGunBoxBlack"..b, getPos(big_gun_box_black[b]), getObj(big_gun_box_black[b]):GetRotation()) end end
for g=1,2 do CreateBigGunBoxGreen("BigGunBoxGreen"..g, getPos(big_gun_box_green[g]), getObj(big_gun_box_green[g]):GetRotation()) end
for f=1,19 do if random(2) == 1 then CreateFlatGunBox("FlatGunBox"..f, getPos(flat_gun_box[f]), getObj(flat_gun_box[f]):GetRotation()) end end trigger:Deactivate()

local small_gun_box = {"GunBox_1_loc", "GunBox_3_loc", "GunBox_9_loc", "GunBox_10_loc", "GunBox_14_loc", "GunBox_17_loc", "GunBox_20_loc", "GunBox_24_loc", "GunBox_26_loc", "GunBox_27_loc", "GunBox_28_loc", "GunBox_33_loc", "GunBox_39_loc", "GunBox_40_loc"} local big_gun_box_black = {"GunBox_11_loc", "GunBox_12_loc", "GunBox_25_loc", "GunBox_30_loc", "GunBox_36_loc"} local big_gun_box_green = {"GunBox_2_loc", "GunBox_38_loc"} local flat_gun_box = {"GunBox_4_loc", "GunBox_5_loc", "GunBox_6_loc", "GunBox_7_loc", "GunBox_8_loc", "GunBox_13_loc", "GunBox_15_loc", "GunBox_16_loc", "GunBox_18_loc", "GunBox_19_loc", "GunBox_21_loc", "GunBox_22_loc", "GunBox_23_loc", "GunBox_29_loc", "GunBox_31_loc", "GunBox_32_loc", "GunBox_34_loc", "GunBox_35_loc", "GunBox_37_loc"}
for s=1,14 do LOG(small_gun_box[s].." "..tostring(getObj("SmallGunBox"..s):GetPosition())) end
for b=1,5 do LOG(big_gun_box_black[b].." "..tostring(getObj("BigGunBoxBlack"..b):GetPosition())) end
for g=1,2 do LOG(big_gun_box_green[g].." "..tostring(getObj("BigGunBoxGreen"..g):GetPosition())) end
for f=1,19 do LOG(flat_gun_box[f].." "..tostring(getObj("FlatGunBox"..f):GetPosition())) end trigger:Deactivate()

local med_box = {"MedBox_2_loc", "MedBox_3_loc", "MedBox_6_loc", "MedBox_7_loc", "MedBox_11_loc", "MedBox_12_loc"} local med_bag = {"MedBox_1_loc", "MedBox_4_loc", "MedBox_5_loc", "MedBox_8_loc", "MedBox_9_loc", "MedBox_10_loc", "MedBox_13_loc", "MedBox_14_loc"} local podkrutka = random(0, 5)
for w = 1, 6 do if random(100) >= 20 then CreateMedWoodBox("MedWoodBox"..w, getPos(med_box[w]), getObj(med_box[w]):GetRotation()) end end
for b = 1, 8 do if random(100) >= 20 then CreateMedBag("MedBag"..b, getPos(med_bag[b]), getObj(med_bag[b]):GetRotation(), podkrutka) end end trigger:Deactivate()
